mapper.insert:
INSERT INTO product_label_versions (
    product_code, version_label, note, food_type, net_weight, ingredients_text, allergens,
    manufacture_report_no, packaging_material, shelf_life_months, shelf_life_unit, storage,
    layout, extra, is_current, created_at, created_by
) VALUES (
    #{productCode}, #{versionLabel}, #{note}, #{foodType}, #{netWeight}, #{ingredientsText}, #{allergens},
    #{manufactureReportNo}, #{packagingMaterial}, #{shelfLifeMonths, jdbcType=INTEGER}, #{shelfLifeUnit},
    (SELECT sm.item_code FROM tb_common_code_item sm JOIN tb_common_code_group smg ON smg.common_code_group_id = sm.group_id AND smg.group_code = 'STORAGE_METHOD' JOIN tb_tenant smt ON smt.tenant_id = smg.tenant_id AND smt.tenant_code = 'SONGYEON' WHERE NULLIF(#{storage, jdbcType=VARCHAR}, '') IS NOT NULL AND (sm.item_code = #{storage, jdbcType=VARCHAR} OR sm.item_nm = #{storage, jdbcType=VARCHAR} OR (split_part(sm.item_nm, '(', 1) <> '' AND strpos(#{storage, jdbcType=VARCHAR}, split_part(sm.item_nm, '(', 1)) > 0)) ORDER BY CASE WHEN sm.item_code = #{storage, jdbcType=VARCHAR} THEN 0 WHEN sm.item_nm = #{storage, jdbcType=VARCHAR} THEN 1 ELSE 2 END, sm.sort_order, sm.item_code LIMIT 1),
    #{layoutJson}, #{extraJson}, #{isCurrent, jdbcType=INTEGER}, #{createdAt}, #{createdBy}
)

mapper.select:
SELECT id AS "id", name AS "name", size AS "size", layout AS "layoutJson"
FROM label_templates
WHERE id = #{id}
